   472  /************************************************************************/
   473  /*                     pj_geodetic_to_geocentric()                      */
   474  /************************************************************************/
   475
   476  int pj_geodetic_to_geocentric( double a, double es,
   477                                 long point_count, int point_offset,
   478                                 double *x, double *y, double *z )
   479
   480  {
   481      double b;
   482      int    i;
   483      GeocentricInfo gi;
   484      int ret_errno = 0;
   485
   486      if( es == 0.0 )
   487          b = a;
   488      else
   489          b = a * sqrt(1-es);
   490
   491      if( pj_Set_Geocentric_Parameters( &gi, a, b ) != 0 )
   492      {
   493          return PJD_ERR_GEOCENTRIC;
   494      }
   495
   496      for( i = 0; i < point_count; i++ )
   497      {
   498          long io = i * point_offset;
   499
   500          if( x[io] == HUGE_VAL  )
   501              continue;
   502
   503          if( pj_Convert_Geodetic_To_Geocentric( &gi, y[io], x[io], z[io],
   504                                                 x+io, y+io, z+io ) != 0 )
   505          {
   506              ret_errno = -14;
   507              x[io] = y[io] = HUGE_VAL;
   508              /* but keep processing points! */
   509          }
   510      }
   511
   512      return ret_errno;
   513  }
